diff --git a/game/core/save.js b/game/core/save.js
new file mode 100644
index 0000000..7f34288
--- /dev/null
+++ b/game/core/save.js
@@ -0,0 +1,103 @@
+// VROOM VROOM - Save envelope + migration chain
+// Every save (localStorage and portable save codes) is stored as
+//   { schema: <int>, player: <player object> }
+// and read back through decode(), which walks the save forward through
+// MIGRATIONS until it reaches SCHEMA. Older shapes count as schema 0:
+//   - a raw player object (what localStorage held before this module)
+//   - a legacy save code payload { v: <game version>, p: <player> }
+// A save from a newer schema than this build knows is refused, never
+// half-loaded.
+//
+// Changing the player's shape? Bump SCHEMA and append one migration that
+// takes a schema N player and returns a schema N+1 player.
+//
+// Loads as a plain <script> (sets window.VroomSave) and under Node for tests
+// (module.exports).
+
+(function (root) {
+    const SCHEMA = 1;
+
+    // MIGRATIONS[n] upgrades a schema n player to schema n + 1.
+    const MIGRATIONS = [
+        // 0 -> 1: introduces the envelope; the player's fields are unchanged.
+        function (player) { return player; }
+    ];
+
+    class SaveError extends Error {
+        constructor(message) {
+            super(message);
+            this.name = 'SaveError';
+        }
+    }
+
+    function isPlainObject(value) {
+        return value !== null && typeof value === 'object' && !Array.isArray(value);
+    }
+
+    // Every player the game has ever created starts with a string name, so
+    // this is the floor that keeps an arbitrary object from passing as a save.
+    function isPlayer(value) {
+        return isPlainObject(value) && typeof value.name === 'string';
+    }
+
+    function encode(player) {
+        if (!isPlainObject(player)) {
+            throw new SaveError('Cannot save: there is no player to save.');
+        }
+        return { schema: SCHEMA, player: player };
+    }
+
+    // Work out which schema a stored value is in and pull the player out.
+    function unwrap(data) {
+        if (Object.prototype.hasOwnProperty.call(data, 'schema')) {
+            if (!Number.isInteger(data.schema) || data.schema < 0) {
+                throw new SaveError('Save is damaged: unknown schema "' + data.schema + '".');
+            }
+            return { schema: data.schema, player: data.player };
+        }
+        if (Object.prototype.hasOwnProperty.call(data, 'p') && Object.prototype.hasOwnProperty.call(data, 'v')) {
+            return { schema: 0, player: data.p };
+        }
+        return { schema: 0, player: data };
+    }
+
+    // data: a parsed save, or the JSON text of one.
+    function decode(data) {
+        if (typeof data === 'string') {
+            try {
+                data = JSON.parse(data);
+            } catch (error) {
+                throw new SaveError('Save is damaged: it is not valid JSON.');
+            }
+        }
+        if (!isPlainObject(data)) {
+            throw new SaveError('Save is damaged: expected an object.');
+        }
+
+        const found = unwrap(data);
+        if (found.schema > SCHEMA) {
+            throw new SaveError(
+                'This save comes from a newer version of VROOM VROOM (save schema ' +
+                found.schema + ', this game reads up to ' + SCHEMA +
+                '). Update the game to load it.'
+            );
+        }
+        if (!isPlayer(found.player)) {
+            throw new SaveError('Save is damaged: it has no player data.');
+        }
+
+        let player = found.player;
+        for (let schema = found.schema; schema < SCHEMA; schema++) {
+            player = MIGRATIONS[schema](player);
+        }
+        return { schema: SCHEMA, player: player };
+    }
+
+    const VroomSave = { SCHEMA, MIGRATIONS, SaveError, encode, decode };
+
+    if (root) {
+        root.VroomSave = VroomSave;
+    } else {
+        module.exports = VroomSave;
+    }
+})(typeof window !== 'undefined' ? window : undefined);
diff --git a/game/core/save.test.mjs b/game/core/save.test.mjs
new file mode 100644
index 0000000..785c9ce
--- /dev/null
+++ b/game/core/save.test.mjs
@@ -0,0 +1,86 @@
+// Run with: node --test game/core/
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import VroomSave from './save.js';
+
+const { SCHEMA, MIGRATIONS, SaveError, encode, decode } = VroomSave;
+
+// A player shaped like the ones pre-envelope builds wrote to localStorage.
+function legacyPlayer() {
+    return {
+        name: 'Dale Brakeman',
+        skinTone: 3,
+        selectedCar: { model: 'beater', color: '#6b5b4b' },
+        sentence: 4,
+        prisonDays: 12,
+        prisonStartTime: 1760000000000,
+        lastPlayed: 1760100000000,
+        money: 85,
+        cigarettes: 7,
+        tattoos: [{ design: [[1, 0], [0, 1]], infected: false, placement: 'leftArm' }],
+        gangRep: { safeDrivers: 10, turnSignals: 0, roadWarriors: 3 },
+        randomEventHistory: [{ id: 'cellmate_theft', day: 9 }]
+    };
+}
+
+test('SCHEMA is a positive integer with one migration per step', () => {
+    assert.ok(Number.isInteger(SCHEMA) && SCHEMA >= 1);
+    assert.equal(MIGRATIONS.length, SCHEMA);
+});
+
+test('a legacy raw player decodes to the current envelope with fields unchanged', () => {
+    const decoded = decode(legacyPlayer());
+    assert.deepEqual(decoded, { schema: SCHEMA, player: legacyPlayer() });
+});
+
+test('a legacy raw player stored as JSON text decodes the same way', () => {
+    const decoded = decode(JSON.stringify(legacyPlayer()));
+    assert.deepEqual(decoded, { schema: SCHEMA, player: legacyPlayer() });
+});
+
+test('a legacy {v, p} save code decodes to the current envelope with fields unchanged', () => {
+    const decoded = decode({ v: '4.0.0', p: legacyPlayer() });
+    assert.deepEqual(decoded, { schema: SCHEMA, player: legacyPlayer() });
+});
+
+test('a legacy save code survives the base64 wrapping the game uses', () => {
+    const code = btoa(encodeURIComponent(JSON.stringify({ v: '4.0.0', p: legacyPlayer() })));
+    const decoded = decode(decodeURIComponent(atob(code)));
+    assert.deepEqual(decoded, { schema: SCHEMA, player: legacyPlayer() });
+});
+
+test('an envelope from a future schema is refused with a clear message', () => {
+    assert.throws(
+        () => decode({ schema: SCHEMA + 1, player: legacyPlayer() }),
+        (error) => error instanceof SaveError && /newer version/.test(error.message)
+    );
+});
+
+test('encode then decode round-trips', () => {
+    const envelope = encode(legacyPlayer());
+    assert.deepEqual(envelope, { schema: SCHEMA, player: legacyPlayer() });
+    assert.deepEqual(decode(JSON.parse(JSON.stringify(envelope))), envelope);
+    assert.deepEqual(decode(JSON.stringify(envelope)), envelope);
+});
+
+test('damaged saves are refused rather than half-loaded', () => {
+    const damaged = [
+        'not json {',
+        'null',
+        '[]',
+        42,
+        { schema: 'one', player: legacyPlayer() },
+        { schema: -1, player: legacyPlayer() },
+        { schema: SCHEMA },
+        { v: '4.0.0', p: null },
+        {},
+        { v: '4.0.0', p: {} }
+    ];
+    for (const input of damaged) {
+        assert.throws(() => decode(input), SaveError, 'expected refusal for ' + JSON.stringify(input));
+    }
+});
+
+test('encode refuses a missing player', () => {
+    assert.throws(() => encode(null), SaveError);
+});
