diff --git a/game/core/validation-contract.test.mjs b/game/core/validation-contract.test.mjs
new file mode 100644
index 0000000..d406688
--- /dev/null
+++ b/game/core/validation-contract.test.mjs
@@ -0,0 +1,107 @@
+// Run with: node --test game/core/
+//
+// .loom/validation.conf is the check a loom lane runs before it opens a pull
+// request. It is only worth trusting while it says what CI says, so these
+// tests hold it to the pull-request workflows: every command it runs must be
+// the run: line of the workflow step it names.
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { readFileSync, existsSync } from 'node:fs';
+import { fileURLToPath } from 'node:url';
+import path from 'node:path';
+
+const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
+const CONTRACT = path.join(ROOT, '.loom/validation.conf');
+const KINDS = ['lint', 'format', 'type', 'test'];
+// The keys the loom runner accepts; any other non-comment line fails the run.
+const KEYS = new Set(['interpreter', 'submodules', 'setup', 'check']);
+
+function readContract() {
+    return readFileSync(CONTRACT, 'utf8').split('\n');
+}
+
+// "key: value" lines, read the way the runner reads them.
+function settings(lines) {
+    return lines
+        .filter((line) => line.trim() !== '' && !line.startsWith('#'))
+        .map((line) => {
+            const at = line.indexOf(':');
+            return { key: line.slice(0, at), value: line.slice(at + 1).trim(), line };
+        });
+}
+
+// "# kind: ..." records in file order, each with the workflow and step
+// comments that follow it and the command line that closes it.
+function records(lines) {
+    const found = [];
+    let current = null;
+    for (const line of lines) {
+        const kind = line.match(/^# (lint|format|type|test): ?(.*)$/);
+        const field = line.match(/^#\s+(workflow|step): (.+)$/);
+        const command = line.match(/^(setup|check): (.+)$/);
+        if (kind) {
+            current = { kind: kind[1], note: kind[2] };
+            found.push(current);
+        } else if (field && current) {
+            current[field[1]] = field[2].trim();
+        } else if (command && current) {
+            current.command = command[2].trim();
+            current = null;
+        }
+    }
+    return found;
+}
+
+// The run: line of each named step, for single-line run: steps.
+function workflowSteps(text) {
+    const steps = new Map();
+    let name = null;
+    for (const line of text.split('\n')) {
+        const named = line.match(/^\s*- name: (.+)$/);
+        const run = line.match(/^\s*run: (.+)$/);
+        if (named) name = named[1].trim();
+        else if (/^\s*- /.test(line)) name = null;
+        else if (run && name) steps.set(name, run[1].trim());
+    }
+    return steps;
+}
+
+function runsOnPullRequest(text) {
+    const on = text.match(/^on:\n((?:[ \t]+.*\n)+)/m);
+    return on !== null && /^\s+pull_request:?\s*$/m.test(on[1]);
+}
+
+test('the contract exists', () => {
+    assert.ok(existsSync(CONTRACT), `${CONTRACT} is missing`);
+});
+
+test('every line is a comment or a key the runner accepts', () => {
+    for (const { key, value, line } of settings(readContract())) {
+        assert.ok(KEYS.has(key), `unknown line: ${line}`);
+        assert.ok(value.length <= 1000 && /^[ -~]*$/.test(value), `not one line of printable ASCII: ${line}`);
+    }
+});
+
+test('exactly one check line', () => {
+    const checks = settings(readContract()).filter((s) => s.key === 'check');
+    assert.equal(checks.length, 1);
+});
+
+test('lint, format, type and test are recorded in that order', () => {
+    assert.deepEqual(records(readContract()).map((r) => r.kind), KINDS);
+});
+
+test('a kind with no command says why', () => {
+    for (const r of records(readContract()).filter((r) => !r.command)) {
+        assert.match(r.note, /^none\b/, `${r.kind} has no command and no "none" note`);
+    }
+});
+
+test('every command is the run: line of the pull-request workflow step it names', () => {
+    for (const r of records(readContract()).filter((r) => r.command)) {
+        assert.ok(r.workflow && r.step, `${r.kind} command needs workflow: and step:`);
+        const text = readFileSync(path.join(ROOT, r.workflow), 'utf8');
+        assert.ok(runsOnPullRequest(text), `${r.workflow} does not run on pull_request`);
+        assert.equal(workflowSteps(text).get(r.step), r.command, `${r.workflow} step "${r.step}"`);
+    }
+});

