diff --git a/common/jsonesc.c b/common/jsonesc.c
new file mode 100644
index 0000000..bbc7a5b
--- /dev/null
+++ b/common/jsonesc.c
@@ -0,0 +1,83 @@
+/*
+ * See jsonesc.h. The escaping itself is unchanged from what shipper.c always
+ * did; what changed is that running out of room is now reported instead of
+ * quietly producing a shorter string.
+ *
+ * Crash reports are full of things that need escaping: quotes in symbol
+ * names, backslashes, and a great many newlines. Getting this wrong produces
+ * a payload the endpoint rejects with no useful message, so it is the one
+ * function here worth being fussy about.
+ */
+
+#include <stdio.h>
+#include <string.h>
+
+#include "jsonesc.h"
+
+/* How many bytes one input byte becomes once escaped. */
+static size_t escaped_width(unsigned char c)
+{
+    switch (c) {
+        case '"': case '\\': case '\b': case '\f':
+        case '\n': case '\r': case '\t':
+            return 2;
+        default:
+            return c < 0x20 ? 6 : 1;
+    }
+}
+
+int json_append_escaped(char *out, size_t out_len, const char *value)
+{
