+#ifndef JSONESC_H
+#define JSONESC_H
+
+#include <stddef.h>
+
+/**
+ * Appending to a fixed JSON buffer without ever leaving half a value in it.
+ *
+ * The payload builders in shipper.c write into one fixed allocation. The
+ * escaper used to stop copying when that buffer was nearly full and return
+ * nothing, so an oversized crash report became valid-looking JSON holding half
+ * a crash, which was then posted and recorded as sent. A tool whose output is
+ * evidence must not do that.
+ *
+ * Both functions here are all or nothing. Either the whole value is appended
+ * and they return 1, or nothing is appended, @out is left exactly as it was,
+ * and they return 0. Callers check the result and refuse to post a body that
+ * did not fit.
+ *
+ * Pure, and kept out of shipper.c so it can be tested on a host.
+ */
+
+/**
+ * Appends @value to the NUL terminated string in @out as the contents of a JSON
+ * string: quotes, backslashes and control bytes are escaped, everything else
+ * is copied verbatim.
+ *
+ * Returns 1 if all of it fit in @out_len bytes including the terminator, 0 if
+ * not, in which case @out is unchanged.
+ */
+int json_append_escaped(char *out, size_t out_len, const char *value);
+
+/**
+ * Appends @text to @out as is, for the JSON structure around escaped values.
+ * Same contract as json_append_escaped: all of it, or none of it and 0.
+ */
+int json_append_str(char *out, size_t out_len, const char *text);
+
+#endif
