+/*
+ * Host tests for JSON escaping into a fixed buffer.
+ *
+ * The defect these pin down: the escaper stopped copying when the buffer was
+ * nearly full and said nothing, so an oversized crash report shipped as valid
+ * JSON holding half a crash and was recorded as sent. An overflow must now be
+ * reported and must leave nothing behind.
+ *
+ * The other half matters as much. Every report that fits has always been
+ * escaped one particular way, and the backend's parsing depends on it, so a
+ * value that fits must come out byte for byte as it did before. legacy_escape
+ * below is the previous implementation, copied verbatim, as the reference.
+ */
+
+#include <stdio.h>
+#include <string.h>
+
+#include "../../common/jsonesc.h"
+
+static int g_checks;
+static int g_failures;
+
+#define CHECK(cond, ...)                                                      \
+    do {                                                                      \
+        g_checks++;                                                           \
+        if (!(cond)) {                                                        \
+            g_failures++;                                                     \
+            printf("  FAIL %s:%d: ", __func__, __LINE__);                     \
+            printf(__VA_ARGS__);                                              \
+            printf("\n");                                                     \
+        }                                                                     \
+    } while (0)
+
+/* The escaper as it was, kept only as the reference output for values that
+ * fit. Not used for anything that overflows: that behaviour is the bug. */
+static void legacy_escape(char *out, size_t out_len, const char *value)
+{
+    size_t o = strlen(out);
+    const unsigned char *p;
+
+    for (p = (const unsigned char*)value; *p; p++) {
+        if (o + 7 >= out_len)
+            break;
+        switch (*p) {
+            case '"':  out[o++] = '\\'; out[o++] = '"';  break;
+            case '\\': out[o++] = '\\'; out[o++] = '\\'; break;
+            case '\b': out[o++] = '\\'; out[o++] = 'b';  break;
+            case '\f': out[o++] = '\\'; out[o++] = 'f';  break;
+            case '\n': out[o++] = '\\'; out[o++] = 'n';  break;
+            case '\r': out[o++] = '\\'; out[o++] = 'r';  break;
+            case '\t': out[o++] = '\\'; out[o++] = 't';  break;
+            default:
+                if (*p < 0x20) {
+                    snprintf(out + o, out_len - o, "\\u%04x", *p);
+                    o += 6;
+                } else {
+                    out[o++] = (char)*p;
+                }
+                break;
+        }
+    }
+    out[o] = '\0';
+}
+
+static void escapes_to(const char *value, const char *want)
+{
+    char out[256] = "";
+
+    CHECK(json_append_escaped(out, sizeof(out), value) == 1,
+          "a %zu byte value reported overflow in a %zu byte buffer",
+          strlen(value), sizeof(out));
+    CHECK(strcmp(out, want) == 0, "escaped to [%s], wanted [%s]", out, want);
+}
+
+static void test_a_fitting_value_escapes_as_it_always_has(void)
+{
+    escapes_to("plain text", "plain text");
+    escapes_to("say \"hi\"", "say \\\"hi\\\"");
+    escapes_to("C:\\path\\x", "C:\\\\path\\\\x");
+    escapes_to("line1\nline2\r\n", "line1\\nline2\\r\\n");
+    escapes_to("\tPC:\b\f", "\\tPC:\\b\\f");
+    escapes_to("\x01\x1f", "\\u0001\\u001f");
+    /* DEL and anything above 0x7f are not JSON control characters and pass
+     * through as is, which is how UTF-8 in a symbol name survives. */
+    escapes_to("\x7f\xc3\xa9", "\x7f\xc3\xa9");
+    escapes_to("", "");
+}
+
+static void test_every_byte_matches_the_previous_escaper(void)
+{
+    /* Each of the 255 non-NUL bytes on its own, then all of them in a row,
+     * appended to existing content the way the payload builder does. */
+    char value[256];
+    char got[2048], want[2048];
+    int c;
+
+    for (c = 1; c < 256; c++) {
+        value[0] = (char)c;
+        value[1] = '\0';
+        strcpy(got, "{\"v\":\"");
+        strcpy(want, "{\"v\":\"");
+        CHECK(json_append_escaped(got, sizeof(got), value) == 1,
+              "byte 0x%02x reported overflow", c);
+        legacy_escape(want, sizeof(want), value);
+        CHECK(strcmp(got, want) == 0,
+              "byte 0x%02x escaped to [%s], previously [%s]", c, got, want);
+    }
+
+    for (c = 1; c < 256; c++)
+        value[c - 1] = (char)c;
+    value[255] = '\0';
+    strcpy(got, "prefix:");
+    strcpy(want, "prefix:");
+    CHECK(json_append_escaped(got, sizeof(got), value) == 1,
+          "all bytes reported overflow");
+    legacy_escape(want, sizeof(want), value);
+    CHECK(strcmp(got, want) == 0, "all bytes escaped differently than before");
+}
+
+static void test_an_oversized_value_reports_overflow_and_writes_nothing(void)
+{
+    char out[64];
+    char big[200];
+
+    /* A crash report in miniature: far longer than the buffer it goes in. */
+    memset(big, 'A', sizeof(big) - 1);
+    big[sizeof(big) - 1] = '\0';
+
+    strcpy(out, "{\"body\":\"");
+    CHECK(json_append_escaped(out, sizeof(out), big) == 0,
+          "a %zu byte value fit in a %zu byte buffer", strlen(big), sizeof(out));
+    CHECK(strcmp(out, "{\"body\":\"") == 0,
+          "overflow left [%s] behind, a truncated value", out);
+}
+
+static void test_a_value_that_only_overflows_once_escaped_is_refused(void)
+{
+    /* 20 raw bytes fit in 32 easily; 40 escaped ones do not. The raw length
+     * is not the length that matters. */
+    char out[32] = "";
+    const char *newlines = "\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n";
+
+    CHECK(json_append_escaped(out, sizeof(out), newlines) == 0,
+          "40 escaped bytes reported as fitting in 32");
+    CHECK(out[0] == '\0', "overflow left %zu bytes behind", strlen(out));
+}
