+                }
+                if (outside)
+                    LOG_INFO("playerbots.dungeonclear",
+                             "[DC:{}] sealed encounter: device-fleet timed out after {} ms with "
+                             "{} still outside - engaging anyway; that member will be "
+                             "locked out of the fight",
+                             bot->GetName(), now - run.sealedDevicefleetSince, outside->GetName());
+            }
+            else
+            {
+                DcRun::Of(context).sealedDevicefleetSince = 0;   // left the approach; re-arm
+            }
+        }
+        return false;
+    }
+}
