--- /dev/null
+++ b/services/web/static/js/capture_a11y.js
@@ -0,0 +1,77 @@
+/* ============================================================
+   Digital Ledger - accessible sign-in helpers (DESIGN 39a, ISSUE-260)
+
+   Pure, DOM-free, node:test-covered. The capture pod reads the live login
+   page over AT-SPI and returns a snapshot ({title, controls, messages}, see
+   services/worker/capture_a11y_bridge.py); capture.js renders it as real HTML
+   controls. These helpers decide what a screen reader hears for a control,
+   what changed between two snapshots, and which X11 keysyms a typed string
+   becomes on the RFB stream.
+   ============================================================ */
+
+// Bridge roles (ARIA-style) -> the words a screen reader would use.
+const ROLE_LABELS = {
+  button: "button",
+  textbox: "text field",
+  checkbox: "checkbox",
+  radio: "radio button",
+  link: "link",
+  combobox: "combo box",
+  switch: "toggle button",
+  menuitem: "menu item",
+  spinbutton: "number field",
+};
+
+const STATE_LABELS = {
+  focused: "focused",
+  required: "required",
+  checked: "checked",
+  invalid: "invalid entry",
+  expanded: "expanded",
+  pressed: "pressed",
+  disabled: "unavailable",
+};
+
+const TYPEABLE_ROLES = new Set(["textbox", "password", "combobox", "spinbutton"]);
+
+// A password input reads as a text field plus "protected", the way NVDA
+// announces one ("edit, protected"). The bridge never sends its value.
+function roleWords(role) {
+  if (role === "password") return [ROLE_LABELS.textbox, "protected"];
+  return [ROLE_LABELS[role] || role];
+}
+
+export function describeControl(control) {
+  const parts = [control.name || "Unlabeled", ...roleWords(control.role)];
+  for (const state of control.states || []) parts.push(STATE_LABELS[state] || state);
+  if (control.value) parts.push(`contains ${control.value}`);
+  return parts.join(", ");
+}
+
+export function isTypeable(control) {
+  return TYPEABLE_ROLES.has(control.role);
+}
+
+function pageSummary(snap) {
+  const n = snap.controls.length;
+  const head = `Page: ${snap.title}. ${n} control${n === 1 ? "" : "s"}.`;
+  return [head, ...snap.messages].join(" ");
+}
+
+// What to say after a refresh: the whole page when it is new (first load or
+// the title changed - a navigation), otherwise only messages that appeared
+// since the previous snapshot (e.g. "Incorrect password"). "" = stay quiet.
+export function announcementFor(prev, next) {
+  if (!prev || prev.title !== next.title) return pageSummary(next);
+  const seen = new Set(prev.messages);
+  return next.messages.filter((m) => !seen.has(m)).join(" ");
+}
+
+// One keysym per Unicode code point (for...of walks code points, so an astral
+// character is not split into surrogates). `lookup` is noVNC's keysymdef
+// lookup, injected so this module stays DOM- and vendor-free.
+export function keysymsFor(text, lookup) {
+  const out = [];
+  for (const ch of text) out.push(lookup(ch.codePointAt(0)));
+  return out;
+}
