+/* node:test for the accessible sign-in helpers (DESIGN 39a, ISSUE-260). These turn
+   the capture pod's AT-SPI snapshot into what a screen reader announces, and
+   typed text into the keysyms sent over the RFB stream.
+   Run: node --test services/web/static/js/capture_a11y.test.mjs */
+import assert from "node:assert/strict";
+import { test } from "node:test";
+
+import keysyms from "./vendor/novnc/core/input/keysymdef.js";
+import { announcementFor, describeControl, isTypeable, keysymsFor } from "./capture_a11y.js";
+
+test("describeControl reads name, role and states in screen-reader order", () => {
+  const c = { id: "2.0", role: "textbox", name: "Email address", states: ["focused", "required"] };
+  assert.equal(describeControl(c), "Email address, text field, focused, required");
+});
+
+test("describeControl includes a text field's current value", () => {
+  const c = { id: "1", role: "textbox", name: "Email", states: [], value: "<email>" };
+  assert.equal(describeControl(c), "Email, text field, contains <email>");
+});
+
+test("describeControl names unlabeled controls and disabled state plainly", () => {
+  const c = { id: "1", role: "button", name: "", states: ["disabled"] };
+  assert.equal(describeControl(c), "Unlabeled, button, unavailable");
+});
+
+test("describeControl reads a password input as a protected text field", () => {
+  const c = { id: "2.1", role: "password", name: "Password", states: ["required"] };
+  assert.equal(describeControl(c), "Password, text field, protected, required");
+});
+
+test("describeControl falls back to the raw role for an unknown one", () => {
+  assert.equal(describeControl({ id: "1", role: "slider", name: "Volume", states: [] }), "Volume, slider");
+});
+
+test("isTypeable is true only for controls that take text", () => {
+  assert.equal(isTypeable({ role: "textbox" }), true);
+  assert.equal(isTypeable({ role: "password" }), true);
+  assert.equal(isTypeable({ role: "spinbutton" }), true);
+  assert.equal(isTypeable({ role: "button" }), false);
+  assert.equal(isTypeable({ role: "link" }), false);
+});
+
+const page = (title, messages, n = 2) => ({
+  title,
+  messages,
+  controls: Array.from({ length: n }, (_, i) => ({ id: String(i), role: "button", name: `B${i}`, states: [] })),
+});
+
+test("announcementFor announces the page on the first snapshot", () => {
+  assert.equal(
+    announcementFor(null, page("Sign in", ["Sign in to Epic"])),
+    "Page: Sign in. 2 controls. Sign in to Epic",
+  );
+});
+
+test("announcementFor announces a navigation as a new page", () => {
+  const before = page("Sign in", ["Sign in to Epic"]);
