+"""Accessible sign-in routes (DESIGN 39a, ISSUE-260).
+
+/capture/{id}/a11y and /capture/{id}/a11y/activate relay the capture pod's
+AT-SPI view of the live login page to the modal, so a screen-reader user can
+read and operate the page without the noVNC canvas. Same owner + RUNNING gates
+as /finalize; the per-session token travels web->pod in the X-Capture-Token
+header and never reaches the browser.
+"""
+
+from datetime import UTC, datetime, timedelta
+from unittest.mock import AsyncMock
