+    "controls": [{"id": "2.0", "role": "textbox", "name": "Email", "states": []}],
+    "messages": ["Sign in"],
+    "truncated": False,
+}
+
+
+def _session(db, *, owner_id="<redacted>", status=CaptureSessionStatus.RUNNING, pod_name="job-x"):
+    if not db.query(UserAccount).filter_by(id=owner_id).first():
+        db.add(UserAccount(id=owner_id, email=f"{owner_id}@x.com", display_name=owner_id))
+        db.commit()
+    session = CaptureSession(
+        owner_id=owner_id,
+        platform=Platform.EPIC,
+        status=status,
+        callback_token="tok-xyz",
+        pod_name=pod_name,
+        expires_at=datetime.now(UTC) + timedelta(minutes=10),
+    )
+    db.add(session)
+    db.commit()
+    return session
+
+
+class _Resp:
+    def __init__(self, status_code=200, payload=None):
+        self.status_code = status_code
+        self._payload = payload if payload is not None else {}
+
+    def json(self):
+        return self._payload
+
+    def raise_for_status(self):
+        if self.status_code >= 400:
+            request = httpx.Request("GET", "http://pod")
+            raise httpx.HTTPStatusError(
+                "pod error", request=request, response=httpx.Response(self.status_code)
+            )
+
+
+def _fake_pod(monkeypatch, resp=None, error=None):
+    calls = []
+
+    class _FakeClient:
+        def __init__(self, *a, **k):
+            pass
+
+        async def __aenter__(self):
+            return self
+
+        async def __aexit__(self, *a):
+            pass
+
+        async def _call(self, method, url, headers, json=None):
+            calls.append({"method": method, "url": url, "headers": headers, "json": json})
+            if error is not None:
+                raise error
+            return resp if resp is not None else _Resp(payload=_SNAPSHOT)
+
+        async def get(self, url, headers):
+            return await self._call("GET", url, headers)
+
+        async def post(self, url, headers, json):
+            return await self._call("POST", url, headers, json)
+
+    monkeypatch.setattr("services.web.routes.capture.httpx.AsyncClient", _FakeClient)
+    monkeypatch.setattr(
+        "services.web.routes.capture.get_pod_ip", AsyncMock(return_value="192.0.2.241")
+    )
+    return calls
+
+
+_ACTIVATE = {"id": "2.0", "role": "textbox", "name": "Email"}
+
