+"""Capture-pod accessibility bridge (DESIGN 39a, ISSUE-260).
+
+The capture modal shows the remote login only as noVNC pixels (DESIGN 40), which
+a screen reader cannot perceive. This bridge gives the modal a parallel,
+structured view of the same live page: it reads the capture pod's real Chrome
+through AT-SPI -- the Linux accessibility bus a screen reader such as Orca uses
+-- and lists the page's interactive controls plus its headings and alerts.
+
+Why AT-SPI and not CDP's Accessibility domain: DESIGN 40 found that Cloudflare
+Turnstile fails any page with the DevTools protocol attached while the challenge
+runs. An AT-SPI client is what a disabled user's own browser has attached, not an
+automation fingerprint.
+
+Input never goes through AT-SPI. `activate` focuses the control (which scrolls it
+into view) and then clicks its centre with a real X11 pointer event (xdotool,
+XTest -- the same injection path x11vnc uses for the sighted user's noVNC
+clicks). Typing goes from the browser over the existing RFB socket (capture.js),
+so no text the user types ever passes through this bridge.
+
+Runs as a short-lived CLI under the system python3 (pyatspi is a Debian package,
+not in the uv venv); the control server (capture_session_server.py) spawns it
+per request:
+
+    capture_a11y_bridge.py snapshot
+    capture_a11y_bridge.py activate <id> <role> <name>
+
+It prints one JSON object to stdout and exits 0 (ok), EXIT_CONFLICT (the page
+changed under the request -- the client should refresh its list) or
+EXIT_FAILURE. This module imports only the standard library at the top so the
+uv-venv tests and the control server can import it; pyatspi is imported only
+inside the live adapter.
+"""
+
+import json
+import subprocess
+import sys
+import time
+import traceback
+from collections.abc import Callable
+
+EXIT_OK = 0
+EXIT_FAILURE = 1
+EXIT_CONFLICT = 2
+
+# grab_focus returns as soon as the request is sent; Chrome scrolls the control
+# into view later. activate re-reads the extents every SETTLE_POLL_S until two
+# readings agree, giving up after SETTLE_MAX_READS rather than clicking a
+# position that is still moving.
+SETTLE_POLL_S = 0.05
+SETTLE_MAX_READS = 20
+
+# Bounds on one walk, so a huge or pathological page cannot stall a request.
+MAX_NODES = 4000
+MAX_CONTROLS = 200
+MAX_MESSAGES = 50
+MAX_TEXT = 300
+
+# Roles a user can act on. The walk does not descend into them: a button's
+# child text node is its name, not a separate control.
+CONTROL_ROLES = frozenset(
+    {
+        "button",
+        "textbox",
+        "password",
+        "checkbox",
+        "radio",
+        "link",
+        "combobox",
+        "switch",
+        "menuitem",
+        "spinbutton",
+    }
+)
+# Text-entry roles whose current value is reported. "password" is deliberately
+# absent: its value is never read, let alone sent.
+VALUE_ROLES = frozenset({"textbox", "combobox", "spinbutton"})
+# Roles whose text tells the user where they are and what went wrong. Unlike a
+# control, the walk still descends into them: a paragraph can hold a link, and
+# an alert's text can live in a child paragraph.
+MESSAGE_ROLES = frozenset({"heading", "alert", "status", "paragraph"})
+# States passed through to the client as-is; "disabled" is derived from the
+# absence of "enabled".
+REPORTED_STATES = ("focused", "required", "checked", "invalid", "expanded", "pressed")
+
+# AT-SPI puts U+FFFC in hypertext where an embedded child object sits.
+_EMBEDDED_OBJECT = "\ufffc"
+
+
+class BridgeError(Exception):
+    """A request the bridge could not serve. `code` is the machine-readable
+    reason written to stdout: "stale"/"offscreen" exit EXIT_CONFLICT,
+    "unavailable"/"usage" exit EXIT_FAILURE."""
+
+    def __init__(self, code: str, detail: str):
+        super().__init__(detail)
+        self.code = code
+        self.detail = detail
+
+
+_CONFLICT_CODES = frozenset({"stale", "offscreen"})
+
+
+def _clean(text: str) -> str:
+    return " ".join(text.replace(_EMBEDDED_OBJECT, " ").split())[:MAX_TEXT]
+
+
+def _control_entry(node, control_id: str) -> dict:
+    states = [s for s in REPORTED_STATES if s in node.states]
+    if "enabled" not in node.states:
+        states.append("disabled")
+    entry = {"id": control_id, "role": node.role, "name": _clean(node.name), "states": states}
+    if node.role in VALUE_ROLES:
+        entry["value"] = _clean(node.text())
+    return entry
+
+
+def _message_text(node) -> str:
+    return _clean(node.name) or _clean(node.text())
+
+
+def _visit(node, node_id: str, snap: dict) -> bool:
+    """Record `node` into `snap`; True if the walk should descend into it."""
+    if node.role in CONTROL_ROLES:
+        if "showing" in node.states and len(snap["controls"]) < MAX_CONTROLS:
+            snap["controls"].append(_control_entry(node, node_id))
+        return False
+    if node.role in MESSAGE_ROLES:
+        text = _message_text(node)
+        if "showing" in node.states and text and len(snap["messages"]) < MAX_MESSAGES:
+            snap["messages"].append(text)
+    return True
+
+
+def _child_ids(node, node_id: str) -> list[tuple[object, str]]:
+    prefix = f"{node_id}." if node_id else ""
+    pairs = [(child, f"{prefix}{i}") for i, child in enumerate(node.children())]
+    return [(child, cid) for child, cid in pairs if child is not None]
+
